import os,glob,re,json
from collections import deque
d=os.path.normpath(os.environ['RLM_SESSION_DIR'])
t=open(d+'/../../sessions/'+os.path.basename(d)+'.jsonl').read().replace('\\n','\n'); G={}
for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n',t):
    k,h,w=m[1],int(m[2]),int(m[3])
    rows=[r.split() for r in t[m.end():].split('\n')[:h]]
    if k not in G and all(len(r)==w and all(x.isdigit() for x in r) for r in rows):
        G[k]=[[int(x) for x in r] for r in rows]
print(sorted(G), [len(v) for v in G.values()])

def transform(g):
    R,C=len(g),len(g[0])
    out=[row[:] for row in g]
    gaps=[]
    for r in range(R):
        for c in range(1,C-1):
            if g[r][c]==0 and g[r][c-1]==5 and g[r][c+1]==5:
                gaps.append((r,c))
    for r,c in gaps:
        left=sum(1 for x in g[r][:c] if x==5); right=sum(1 for x in g[r][c+1:] if x==5)
        rr=r-1
        if rr>=0:
            rng=range(0,c+1) if left>right else range(c,C)
            for cc in rng: out[rr][cc]=2
    # fill enclosed: flood from border, walls = 5 and gaps
    wall=set(gaps)|{(r,c) for r in range(R) for c in range(C) if g[r][c]==5}
    seen=set()
    q=deque()
    for r in range(R):
        for c in (0,C-1):
            if (r,c) not in wall and (r,c) not in seen: seen.add((r,c)); q.append((r,c))
    for c in range(C):
        for r in (0,R-1):
            if (r,c) not in wall and (r,c) not in seen: seen.add((r,c)); q.append((r,c))
    while q:
        r,c=q.popleft()
        for dr,dc in((1,0),(-1,0),(0,1),(0,-1)):
            nr,nc=r+dr,c+dc
            if 0<=nr<R and 0<=nc<C and (nr,nc) not in wall and (nr,nc) not in seen:
                seen.add((nr,nc)); q.append((nr,nc))
    for r in range(R):
        for c in range(C):
            if (r,c) not in wall and (r,c) not in seen:
                out[r][c]=2
    for r,c in gaps: out[r][c]=2
    return out

for k in sorted(G):
    if k.startswith('Demo'):
